import math

def solve():
    satisfying_n = []
    for n in range(2, 13):
        is_satisfying = True

        # We only need to check k such that 1 <= k < n and gcd(k, n) = 1
        for k in range(1, n):
            if math.gcd(k, n) == 1:
                # Check if k^2 === 1 (mod n)
                if (k * k) % n != 1:
                    is_satisfying = False
                    break

        if is_satisfying:
            satisfying_n.append(n)

    return satisfying_n

print(solve())

